import{_ as s,o as n,c as i,ah as a}from"./chunks/framework.QnJvYzEf.js";const r="/projects/TurboPi/en/advanced/assets/image2.DxSdojJO.png",t="/projects/TurboPi/en/advanced/assets/image3.D8Mpte8R.png",c="data:image/jpeg;base64,",p="/projects/TurboPi/en/advanced/assets/image5.CRsGpRxI.png",d="/projects/TurboPi/en/advanced/assets/image6.BBZl089s.png",l="/projects/TurboPi/en/advanced/assets/image8.Jk_Ezsvh.png",h="/projects/TurboPi/en/advanced/assets/image9.ht43AUU0.png",g="/projects/TurboPi/en/advanced/assets/image10.DnwrTVif.png",m="/projects/TurboPi/en/advanced/assets/image11.BkqzGNru.png",A="/projects/TurboPi/en/advanced/assets/image12.TeB_tcJF.png",u="/projects/TurboPi/en/advanced/assets/image14.DfxOCizM.png",w="/projects/TurboPi/en/advanced/assets/image2.DxSdojJO.png",o="/projects/TurboPi/en/advanced/assets/image3.CsVuRf4b.png",b="data:image/jpeg;base64,",f="/projects/TurboPi/en/advanced/assets/image5.CRsGpRxI.png",y="/projects/TurboPi/en/advanced/assets/image6.BBZl089s.png",Q="/projects/TurboPi/en/advanced/assets/image8.j5UeaH8g.png",N="/projects/TurboPi/en/advanced/assets/image10.ZtdVVw7C.png",v="/projects/TurboPi/en/advanced/assets/image11.CrHy1ndc.png",D="/projects/TurboPi/en/advanced/assets/image12.cxePItGO.png",k="/projects/TurboPi/en/advanced/assets/image14.CqkV501L.png",P="/projects/TurboPi/en/advanced/assets/image15.Bop_b8cY.png",_="/projects/TurboPi/en/advanced/assets/image16.r-1QbRAh.png",C="/projects/TurboPi/en/advanced/assets/image17.zJKqChxN.png",W=JSON.parse('{"title":"7. Network Configuration for Robot","description":"","frontmatter":{},"headers":[],"relativePath":"docs/7.network_configuration.md","filePath":"docs/7.network_configuration.md"}'),E={name:"docs/7.network_configuration.md"};function q(B,e,R,T,M,x){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_7-network-configuration-for-robot" tabindex="-1">7. Network Configuration for Robot <a class="header-anchor" href="#_7-network-configuration-for-robot" aria-label="Permalink to &quot;7. Network Configuration for Robot&quot;">​</a></h1><h2 id="_7-1-changing-wi-fi-name-and-password" tabindex="-1">7.1 Changing Wi-Fi Name and Password <a class="header-anchor" href="#_7-1-changing-wi-fi-name-and-password" aria-label="Permalink to &quot;7.1 Changing Wi-Fi Name and Password&quot;">​</a></h2><p>When connecting a computer to the hotspot generated by the Raspberry Pi, the hotspot name usually starts with <strong>&quot;HW&quot;</strong>. However, if there are multiple TurboPi devices nearby, it may cause accidental connections. This section provides a detailed explanation of how to modify the default Wi-Fi name and password.</p><p>(1) Power on the TurboPi, and connect your computer to the hotspot it generates, typically named starting with <strong>&quot;HW&quot;</strong>. When connecting for the first time, the default password is hiwonder.</p><img loading="lazy" height="138" width="359" class="common_img" src="'+r+'"><p>(2) Establish a VNC connection with the TurboPi.</p><img loading="lazy" height="1025" width="1768" class="common_img" src="'+t+'"><p>(3) Click the icon <img loading="lazy" height="37" width="50" src="'+c+'"> in the top-left corner of the desktop, or press <strong>Ctrl + Alt + T t</strong>o open the terminal.</p><img loading="lazy" height="212" width="751" class="common_img" src="'+p+'"><p>(4) In the terminal, enter the command &quot;<strong>cd hiwonder-toolbox</strong>&quot; and press Enter to navigate to the Wi-Fi configuration directory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><img loading="lazy" height="161" width="700" class="common_img" src="'+d+'"><p>(5) Next, open the Wi-Fi configuration file using the command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim wifi_conf.py</span></span></code></pre></div><p>(6) The interface is shown as below:</p><img loading="lazy" height="234" width="702" class="common_img" src="'+l+'"><p>(7) Enter :set number and press Enter to show line numbers, you can set as needed.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:set number</span></span></code></pre></div><img loading="lazy" height="132" width="702" class="common_img" src="'+h+'"><p>(8) Press the <strong>&quot;i&quot;</strong> key on your keyboard, and you will see <strong>&quot;--INSERT--&quot;</strong> at the bottom left of the screen, indicating that the file is now editable. You can now modify the file according to your needs, referring to the corresponding comments.</p><img loading="lazy" height="446" width="700" class="common_img" src="'+g+'"><p>(9) Suppose you want to change the Wi-Fi name of the Raspberry Pi to <strong>&quot;HW-TurboPi&quot;</strong> and the password to <strong>&quot;123456789&quot;</strong>, then you only need to modify the program as shown in the figure below.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>You can set the Wi-Fi name and password according to your needs, but the following rules must be followed:</p><p>① The set Wi-Fi name cannot be the same as any existing router name and must start with &quot;<strong>HW</strong>&quot;.</p><p>② The password must be at least 8 characters.</p></section><p>To restore the original settings, simply reverse the above operations.</p><img loading="lazy" height="191" width="700" class="common_img" src="'+m+'"><p>(10) After completing the modifications, press the &quot;<strong>ESC</strong>&quot; key on your keyboard, then enter :wq to save and exit the file.</p><img loading="lazy" height="448" width="701" class="common_img" src="'+A+'"><p>(11) Enter the command <strong>&quot;sudo systemctl restart hw_wifi.service&quot;</strong> in the terminal, and the VNC will automatically disconnect and restart.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl restart hw_wifi.service</span></span></code></pre></div><p>(12) Wait for the device to reboot and connect to the <strong>&quot;HW-TurboPi&quot;</strong> network, with the password <strong>&quot;123456789&quot;.</strong></p><img loading="lazy" height="451" width="989" class="common_img" src="'+u+'" style="width:350px;"><p>(13) Once connected successfully, wait for the VNC interface to refresh.</p><p>(14) After successful connection, the VNC remote desktop will display the desktop as shown in the figure below.</p><img loading="lazy" height="1025" width="1768" class="common_img" src="'+t+'"><h2 id="_7-2-modify-network-connection-mode" tabindex="-1">7.2 Modify Network Connection Mode <a class="header-anchor" href="#_7-2-modify-network-connection-mode" aria-label="Permalink to &quot;7.2 Modify Network Connection Mode&quot;">​</a></h2><p>This section uses TurboPi as an example, and the same content applies to other products.</p><p>The previous lessons introduce how to connect the robot using LAN mode via the app on the phone. This section will explain in detail how to switch to LAN mode by modifying the Wi-Fi configuration file.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>After modification, if you want to switch back to direct connection mode, simply reverse the steps described below.</p></section><p>(1) Power on the robot and connect your computer to the hotspot generated by the robot, usually starts with <strong>&quot;HW&quot;.</strong></p><img loading="lazy" height="138" width="359" class="common_img" src="'+w+'"><p>(2) Establish a VNC connection with the robot.</p><img loading="lazy" height="735" width="1268" class="common_img" src="'+o+'"><p>(3) Click the icon <img loading="lazy" height="37" width="50" src="'+b+'"> in the top-left corner of the desktop, or press Ctrl + Alt + T to open the terminal.</p><img loading="lazy" height="212" width="751" class="common_img" src="'+f+'"><p>(4) In the terminal, enter the command <strong>&quot;cd hiwonder-toolbox&quot;</strong> and press Enter to navigate to the Wi-Fi configuration directory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><img loading="lazy" height="161" width="700" class="common_img" src="'+y+'"><p>(5) Next, open the Wi-Fi configuration file using the command：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim wifi_conf.py</span></span></code></pre></div><p>(6) The interface is shown as below:</p><img loading="lazy" height="262" width="745" class="common_img" src="'+Q+'"><p>(7) Enter <strong>&quot;:set number&quot;</strong> and press Enter to show line numbers, you can set as needed.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:set number</span></span></code></pre></div><p>(8) Press the <strong>&quot;i&quot;</strong> key on your keyboard, and you will see <strong>&quot;--INSERT--&quot;</strong> at the bottom left of the screen.</p><img loading="lazy" height="484" width="755" class="common_img" src="'+N+'"><p>(9) Change the mode to STA (LAN) mode. Modify the program as shown in the example below.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The following uses connection to the &quot;<strong>Hiwonder</strong>&quot; network as an example. You can modify it based on your need. To revert to the original configuration, change HW-WIFI-MODE = 2 back to 1 to switch the Wi-Fi mode to AP mode.</p></section><p><strong>Avoid using campus networks or Wi-Fi names that contain Chinese characters.</strong></p><img loading="lazy" height="299" width="750" class="common_img" src="'+v+'"><p>(10) After completing the modifications, press the <strong>&quot;ESC&quot;</strong> key on your keyboard, then enter :wq to save and exit the file.</p><img loading="lazy" height="446" width="699" class="common_img" src="'+D+'"><p>(11) Enter the command <strong>&quot;sudo systemctl restart wifi.service&quot;</strong> in the terminal, and the VNC will automatically disconnect and restart. If the robot&#39;s LED2 remains steadily on, it indicates the mode has been successfully changed to LAN.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl restart wifi.service</span></span></code></pre></div><p>(12) To check the Raspberry Pi&#39;s IP address using the mobile app, first connect your phone to the same LAN, <strong>&quot;Hiwonder&quot;</strong> in this case.</p><img loading="lazy" height="867" width="1049" class="common_img" src="'+k+'" style="width:400px;"><p>(13) Open the WonderPi app and select <strong>&quot;Basic&quot; &gt; &quot;TurboPi&quot;</strong>.</p><img loading="lazy" height="378" width="746" class="common_img" src="'+P+'" style="width:700px;"><p>(14) Once the app connects to TurboPi, you&#39;ll see an icon like the one below indicating a successful connection.</p><img loading="lazy" height="292" width="563" class="common_img" src="'+_+'" style="width:700px;"><p>(15) Long-press the corresponding icon of your robot in the app to view its assigned IP address and Device ID.</p><img loading="lazy" height="585" width="1268" class="common_img" src="'+C+'"><p>(16) Open the VNC software, enter the IP 192.168.11.109 to connect.</p><p>(17) After a successful connection, the VNC remote desktop will display as shown below.</p><img loading="lazy" height="735" width="1268" class="common_img" src="'+o+'">',74)])])}const J=s(E,[["render",q]]);export{W as __pageData,J as default};
